package com.gymflow.membership; import com.gymflow.gym.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class MembershipPlanService {private final MembershipPlanRepository plans;private final GymRepository gyms;public MembershipPlanService(MembershipPlanRepository p,GymRepository g){plans=p;gyms=g;}
 @Transactional public MembershipPlanResponse create(UUID gymId,MembershipPlanRequest r){Gym gym=gyms.findById(gymId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Gimnasio no encontrado."));if(plans.existsByGym_IdAndNameIgnoreCase(gymId,r.name().trim()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Ya existe un plan con ese nombre.");return MembershipPlanResponse.from(plans.save(new MembershipPlan(gym,r.name().trim(),r.description(),r.durationValue(),r.durationUnit(),r.price())));}
 @Transactional(readOnly=true) public List<MembershipPlanResponse> findAll(UUID gymId){if(!gyms.existsById(gymId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Gimnasio no encontrado.");return plans.findAllByGym_IdOrderByName(gymId).stream().map(MembershipPlanResponse::from).toList();}}
